import {ToolRegistry} from './registry.js';
import type {ToolDefinition} from '../../types/ai.js';

const weatherDefinition = (extra: Record<string, unknown> = {}): ToolDefinition => ({
  name: 'get_weather',
  description: 'Get weather for a location',
  inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location'], ...extra},
});

describe('ToolRegistry', () => {
  it('passes valid input with an unlisted extra property to the executor unchanged, exactly once', async () => {
    const registry = new ToolRegistry();
    const received: Record<string, unknown>[] = [];
    registry.register(weatherDefinition(), async input => {
      received.push(input);
      return 'sunny';
    });

    const response = await registry.execute('get_weather', {location: 'Berlin', unit: 'c'});

    expect({response, received}).toEqual({
      response: {result: 'sunny'},
      received: [{location: 'Berlin', unit: 'c'}],
    });
  });

  it('throws Unknown tool for an unregistered name', async () => {
    const registry = new ToolRegistry();

    await expect(registry.execute('missing', {})).rejects.toThrow('Unknown tool: missing');
  });

  it('validates a function-valued definition against the schema current at that call', async () => {
    const registry = new ToolRegistry();
    let calls = 0;
    let requireUnit = false;
    registry.register(
      () => weatherDefinition(requireUnit ? {required: ['location', 'unit']} : {}),
      async () => {
        calls += 1;
        return 'ok';
      }
    );

    const before = await registry.execute('get_weather', {location: 'Berlin'});
    requireUnit = true;
    const after = await registry.execute('get_weather', {location: 'Berlin'});

    expect({before: before.result, afterRejected: after.result.includes('unit'), calls}).toEqual({
      before: 'ok',
      afterRejected: true,
      calls: 1,
    });
  });
});
